const ble = MethodChannel('proxyproof/ble');
void main() => runApp(const ProxyProofApp());

class Api {
  // Android emulator -> host machine. For a physical phone use http://YOUR_LAN_IP:8000
  static String baseUrl = 'http://10.0.2.2:8000';
  static String? token;
  static String role = '';
  static String username = '';
  static Future<dynamic> call(String path,{String method='GET',Map<String,dynamic>? body,bool auth=true}) async {
    final headers={'Content-Type':'application/json','Accept':'application/json'};
    if(auth && token!=null) headers['Authorization']='Bearer $token';
    final uri=Uri.parse('${baseUrl.trim().replaceAll(RegExp(r'/$'), '')}$path');
    late http.Response response;
    if(method=='POST') response=await http.post(uri,headers:headers,body:jsonEncode(body??{})).timeout(const Duration(seconds:12));
    else if(method=='DELETE') response=await http.delete(uri,headers:headers).timeout(const Duration(seconds:12));
    else response=await http.get(uri,headers:headers).timeout(const Duration(seconds:12));
    dynamic data;
    try { data=jsonDecode(response.body); } catch (_) { data=response.body; }
    if(response.statusCode<200||response.statusCode>=300){throw Exception(data is Map?(data['detail']??'Request failed'):'HTTP ${response.statusCode}');}
    return data;
  }
}
String err(Object e)=>e.toString().replaceFirst('Exception: ','');

class ProxyProofApp extends StatelessWidget { const ProxyProofApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'ProxyProof',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff175cd3)),useMaterial3:true),home:const LoginPage()); }

class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage>{
  final username=TextEditingController(text:'organiser'); final password=TextEditingController(text:'organiser123'); final url=TextEditingController(text:Api.baseUrl); bool busy=false;
  Future<String> _deviceId() async {final p=await SharedPreferences.getInstance(); var id=p.getString('device_id'); if(id==null){id='android-${DateTime.now().millisecondsSinceEpoch}-${DateTime.now().microsecond}';await p.setString('device_id',id);} return id;}
  Future<void> login() async {setState(()=>busy=true);try{Api.baseUrl=url.text.trim();final d=await Api.call('/api/login',method:'POST',auth:false,body:{'username':username.text.trim(),'password':password.text,'device_id':await _deviceId()});Api.token=d['access_token'];Api.role=d['role'];Api.username=d['username'];if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const HomePage()));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}finally{if(mounted)setState(()=>busy=false);}}
  @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.bluetooth_searching,size:64,color:Color(0xff175cd3)),const SizedBox(height:8),Text('ProxyProof',textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const Text('Bluetooth attendance MVP',textAlign:TextAlign.center),const SizedBox(height:28),TextField(controller:url,decoration:const InputDecoration(labelText:'Backend URL',helperText:'Emulator: 10.0.2.2 • Phone: computer LAN IP',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:username,decoration:const InputDecoration(labelText:'Username',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),const SizedBox(height:18),FilledButton(onPressed:busy?null:login,child:Text(busy?'Signing in…':'Sign in')),const SizedBox(height:18),const Text('Organiser: organiser / organiser123\nStudent: student1 / student123\nStudent 2: student2 / student123',style:TextStyle(fontSize:13)),const SizedBox(height:8),const Text('Use two physical Android phones for real BLE testing.',style:TextStyle(fontSize:12,color:Colors.black54))])))));
}

class HomePage extends StatefulWidget {const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{
 List<dynamic> sessions=[]; bool loading=false,advertising=false,scanning=false; int? activeId; String status=''; Timer? refreshTimer; bool get organiser=>Api.role=='organiser';
 @override void initState(){super.initState();load();refreshTimer=Timer.periodic(const Duration(seconds:4),(_)=>load(silent:true));}
 @override void dispose(){refreshTimer?.cancel();try{ble.invokeMethod('stopAdvertising');ble.invokeMethod('stopScan');}catch(_){}super.dispose();}
 Future<void> load({bool silent=false})async{try{final d=await Api.call('/api/sessions');if(mounted)setState(()=>sessions=List<dynamic>.from(d));}catch(e){if(!silent&&mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}
 Future<void> createSession()async{final c=TextEditingController(text:'CSE Lecture');final title=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Start session'),content:TextField(controller:c,decoration:const InputDecoration(labelText:'Session title')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('Start'))]));if(title==null||title.length<2)return;try{final s=await Api.call('/api/sessions',method:'POST',body:{'title':title,'duration_seconds':300});activeId=s['id'];setState(()=>status='Session #$activeId created; starting BLE broadcast…');await refreshBeacon();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}
 Future<void> refreshBeacon()async{if(activeId==null)return;try{final d=await Api.call('/api/sessions/$activeId/token');await ble.invokeMethod('startAdvertising',{'sessionId':d['session_id'],'token':d['token']});if(mounted)setState(()=>advertising=true);Future.doWhile(()async{await Future.delayed(const Duration(seconds:3));if(!mounted||!advertising||activeId==null)return false;try{final t=await Api.call('/api/sessions/$activeId/token');await ble.invokeMethod('startAdvertising',{'sessionId':t['session_id'],'token':t['token']});}catch(e){if(mounted)setState(()=>status='Broadcast refresh failed: ${err(e)}');}return mounted&&advertising&&activeId!=null;});}catch(e){setState(()=>status='BLE broadcast error: ${err(e)}');rethrow;}}
 Future<void> scan()async{if(scanning)return;setState(()=>scanning=true);try{final device=(await SharedPreferences.getInstance()).getString('device_id')!;final raw=await ble.invokeMethod<List<dynamic>>('scan',{'durationMs':12000})??[];int marked=0;String last='No ProxyProof beacon found.';for(final x in raw){final d=Map<String,dynamic>.from(x as Map);try{final r=await Api.call('/api/attendance/mark',method:'POST',body:{'session_id':d['session_id'],'token':d['token'],'device_id':device,'rssi':d['rssi']});last=r['status']=='already_marked'?'Attendance was already recorded.':'Attendance marked for session #${d['session_id']}.';marked++;}catch(e){last=err(e);}}if(mounted){setState(()=>status=marked>0?last:last);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(status)));}await load();}catch(e){if(mounted){setState(()=>status=err(e));ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(status)));}}finally{if(mounted)setState(()=>scanning=false);}}
 Future<void> stopSession(int id)async{try{await Api.call('/api/sessions/$id/close',method:'POST');if(activeId==id){activeId=null;advertising=false;await ble.invokeMethod('stopAdvertising');}await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}
 Future<void> history()async{try{final d=await Api.call('/api/students/me/history');if(!mounted)return;showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Attendance history'),content:SingleChildScrollView(child:Text(const JsonEncoder.withIndent('  ').convert(d))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}catch(e){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}
 Future<void> openSession(int id)async{try{final d=await Api.call('/api/sessions/$id/attendance');if(!mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>RosterPage(sessionId:id,attendance:List<dynamic>.from(d),onRefresh:load)));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('ProxyProof'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh)),IconButton(onPressed:organiser?null:history,icon:const Icon(Icons.history)),IconButton(onPressed:()async{Api.token=null;if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const LoginPage()),(_)=>false);},icon:const Icon(Icons.logout))]),floatingActionButton:organiser?FloatingActionButton.extended(onPressed:createSession,icon:const Icon(Icons.add),label:const Text('Start session')):null,body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(Api.username),subtitle:Text(Api.role))),if(!organiser)FilledButton.icon(onPressed:scanning?null:scan,icon:const Icon(Icons.bluetooth_searching),label:Text(scanning?'Scanning…':'Scan / mark attendance')),if(organiser&&activeId!=null)Card(color:Colors.blue.shade50,child:ListTile(title:Text('Broadcasting session #$activeId'),subtitle:Text(status),trailing:IconButton(onPressed:()=>stopSession(activeId!),icon:const Icon(Icons.stop_circle)))),if(status.isNotEmpty)Padding(padding:const EdgeInsets.all(8),child:Text(status)),Text(organiser?'Sessions':'Recent sessions',style:Theme.of(context).textTheme.titleLarge),if(sessions.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('No sessions yet.')), ...sessions.map((raw){final s=Map<String,dynamic>.from(raw);return Card(child:ListTile(leading:Icon(s['active']==true?Icons.radio_button_checked:Icons.event_busy,color:s['active']==true?Colors.green:Colors.grey),title:Text('#${s['id']} — ${s['title']}'),subtitle:Text('${s['starts_at']}\n${s['active']==true?'Active':'Closed'}'),isThreeLine:true,onTap:()=>openSession(s['id']),trailing:organiser&&s['active']==true?IconButton(icon:const Icon(Icons.stop),onPressed:()=>stopSession(s['id'])):null));})])));
}

class RosterPage extends StatefulWidget{final int sessionId;final List<dynamic> attendance;final Future<void> Function({bool silent}) onRefresh;const RosterPage({super.key,required this.sessionId,required this.attendance,required this.onRefresh});@override State<RosterPage> createState()=>_RosterPageState();}
class _RosterPageState extends State<RosterPage>{late List<dynamic> rows;Timer? timer;@override void initState(){super.initState();rows=widget.attendance;timer=Timer.periodic(const Duration(seconds:4),(_)=>reload());}@override void dispose(){timer?.cancel();super.dispose();}Future<void> reload()async{try{final d=await Api.call('/api/sessions/${widget.sessionId}/attendance');if(mounted)setState(()=>rows=List<dynamic>.from(d));}catch(_){} }Future<void> add()async{final c=TextEditingController();final name=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Manual attendance'),content:TextField(controller:c,decoration:const InputDecoration(labelText:'Student username')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('Add'))]));if(name==null||name.isEmpty)return;try{await Api.call('/api/sessions/${widget.sessionId}/manual-add',method:'POST',body:{'student_username':name});await reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}Future<void> remove(String name)async{try{await Api.call('/api/sessions/${widget.sessionId}/attendance/${Uri.encodeComponent(name)}',method:'DELETE');await reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}Future<void> exportCsv()async{try{final r=await http.get(Uri.parse('${Api.baseUrl}/api/sessions/${widget.sessionId}/csv'),headers:{'Authorization':'Bearer ${Api.token}'});if(r.statusCode!=200)throw Exception('CSV export failed');if(mounted)showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('CSV data'),content:SingleChildScrollView(child:SelectableText(r.body)),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(err(e))));}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('Session #${widget.sessionId}'),actions:[IconButton(onPressed:exportCsv,icon:const Icon(Icons.download))]),floatingActionButton:Api.role=='organiser'?FloatingActionButton(onPressed:add,child:const Icon(Icons.person_add)):null,body:ListView(padding:const EdgeInsets.all(16),children:[Text('${rows.length} students marked',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),if(rows.isEmpty)const Text('No attendance yet.'),...rows.map((x){final r=Map<String,dynamic>.from(x);return Card(child:ListTile(leading:const Icon(Icons.check_circle,color:Colors.green),title:Text(r['username']??''),subtitle:Text('${r['marked_at']??''}\nRSSI ${r['rssi']??'-'} • ${r['source']??'ble'}'),isThreeLine:true,trailing:Api.role=='organiser'?IconButton(onPressed:()=>remove(r['username']),icon:const Icon(Icons.remove_circle_outline)):null));})]));}
